async function p(){try{const d="koalastuff_github_repos";let r=null,n=null;try{n=localStorage.getItem(d)}catch{}if(n){const t=JSON.parse(n);Date.now()-t.timestamp<360*60*1e3&&(r=t.data)}if(!r){const t=await fetch("https://api.github.com/users/Shik3i/repos?sort=updated&per_page=100");if(!t.ok)return;r=await t.json();try{localStorage.setItem(d,JSON.stringify({timestamp:Date.now(),data:r}))}catch{}}const o=new Map;r.forEach(t=>{o.set(t.full_name.toLowerCase(),new Date(t.pushed_at||t.updated_at))});const i=document.getElementById("projects-tracker-rows");if(i){const t=Array.from(i.children);t.sort((s,c)=>{const e=s.querySelector(".github-last-updated"),a=c.querySelector(".github-last-updated"),l=e?e.getAttribute("data-github-repo")?.toLowerCase():null,u=a?a.getAttribute("data-github-repo")?.toLowerCase():null,h=l&&o.has(l)?o.get(l).getTime():0;return(u&&o.has(u)?o.get(u).getTime():0)-h}),t.forEach(s=>i.appendChild(s))}document.querySelectorAll(".github-last-updated").forEach(t=>{const s=t.getAttribute("data-github-repo");if(!s)return;const c=o.get(s.toLowerCase());if(c){const e=Math.floor((Date.now()-c.getTime())/864e5);let a="";e===0?a="Updated today":e===1?a="Updated yesterday":e<30?a=`Updated ${e}d ago`:e<365?a=`Updated ${Math.floor(e/30)}mo ago`:a=`Updated ${Math.floor(e/365)}y ago`,t.innerHTML=`<span class="update-dot"></span>${a}`,t.classList.add("has-fresh-data")}})}catch(d){console.error("Failed to fetch github data",d)}}document.addEventListener("astro:page-load",p);
